INSERT INTO mail_templates (slug, name, segment, position, subject, preview, body) VALUES (
  $tpl$holiday-1$tpl$, $tpl$Retail · Email 1 — "Order by November 20 for December 12"$tpl$, $tpl$Retail$tpl$, 1,
  $tpl$Order by Nov 20 for December 12 delivery$tpl$,
  $tpl$The Guadalupe canvas gift guide is up. Framed, rolled, and gallery wrap — from $57.$tpl$,
  $tpl$Dear @firstname,

Two devotional dates are coming up faster than you'd think.

